settings.custom_liquid:
{{ 'relax.css' | asset_url | stylesheet_tag }}
{%- assign v = product.selected_or_first_available_variant -%}
{%- if v.compare_at_price > v.price -%}
  {%- assign saving = v.compare_at_price | minus: v.price -%}
  {%- assign pct = saving | times: 100.0 | divided_by: v.compare_at_price | round -%}
  <div class="relax-promo">
    <span class="relax-promo__badge">−{{ pct }} %</span>
    <span class="relax-promo__text">Offre de lancement : vous économisez {{ saving | money }} aujourd'hui</span>
  </div>
{%- endif -%}
<p class="relax-shipping-note"><span class="relax-icon">{% render 'relax-icon', icon: 'truck' %}</span> Livraison 100 % GRATUITE — chez vous sous 3 à 7 jours ouvrés</p>
